import { MakeLogicType, actions, kea, listeners, path, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

import { TodayListItemField, moveListItemField, orderedListItemFields } from './todayListAppearance'

/** The dialog's unsaved choice: every field in its order, and which of them are checked. */
export interface TodayListAppearanceDraft {
    order: TodayListItemField[]
    checked: TodayListItemField[]
}

const EMPTY_DRAFT: TodayListAppearanceDraft = { order: orderedListItemFields([]), checked: [] }

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayListAppearanceLogicValues {
    dialogOpen: boolean
    draft: TodayListAppearanceDraft
    draftFields: TodayListItemField[]
    fields: TodayListItemField[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayListAppearanceLogicActions {
    closeAppearanceDialog: () => {
        value: true
    }
    moveDraftField: (
        field: TodayListItemField,
        offset: 1 | -1
    ) => {
        field: 'activity' | 'branch' | 'creator' | 'repository' | 'space'
        offset: 1 | -1
    }
    openAppearanceDialog: () => {
        value: true
    }
    saveAppearance: () => {
        value: true
    }
    setDraft: (draft: TodayListAppearanceDraft) => {
        draft: TodayListAppearanceDraft
    }
    setFields: (fields: TodayListItemField[]) => {
        fields: ('activity' | 'branch' | 'creator' | 'repository' | 'space')[]
    }
    toggleDraftField: (
        field: TodayListItemField,
        checked: boolean
    ) => {
        checked: boolean
        field: 'activity' | 'branch' | 'creator' | 'repository' | 'space'
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayListAppearanceLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        draftFields: (draft: TodayListAppearanceDraft) => TodayListItemField[]
    }
}

export type todayListAppearanceLogicType = MakeLogicType<
    todayListAppearanceLogicValues,
    todayListAppearanceLogicActions,
    Record<string, any>,
    todayListAppearanceLogicMeta
>

/** Which details the sidebar's session rows show under their titles, like PostHog Desktop's list item appearance. */
export const todayListAppearanceLogic = kea<todayListAppearanceLogicType>([
    path(['layout', 'today', 'todayListAppearanceLogic']),
    actions({
        openAppearanceDialog: true,
        closeAppearanceDialog: true,
        setDraft: (draft: TodayListAppearanceDraft) => ({ draft }),
        toggleDraftField: (field: TodayListItemField, checked: boolean) => ({ field, checked }),
        moveDraftField: (field: TodayListItemField, offset: -1 | 1) => ({ field, offset }),
        saveAppearance: true,
        setFields: (fields: TodayListItemField[]) => ({ fields }),
    }),
    reducers({
        fields: [[] as TodayListItemField[], { persist: true }, { setFields: (_, { fields }) => fields }],
        dialogOpen: [false, { openAppearanceDialog: () => true, closeAppearanceDialog: () => false }],
        draft: [
            EMPTY_DRAFT,
            {
                setDraft: (_, { draft }) => draft,
                toggleDraftField: (state, { field, checked }) => ({
                    ...state,
                    checked: checked
                        ? [...state.checked.filter((id) => id !== field), field]
                        : state.checked.filter((id) => id !== field),
                }),
                moveDraftField: (state, { field, offset }) => ({
                    ...state,
                    order: moveListItemField(state.order, field, offset),
                }),
            },
        ],
    }),
    selectors({
        draftFields: [
            (s) => [s.draft],
            (draft: TodayListAppearanceDraft): TodayListItemField[] =>
                draft.order.filter((field) => draft.checked.includes(field)),
        ],
    }),
    listeners(({ actions, values }) => ({
        // Each opening starts from what is saved, so a canceled edit does not come back.
        openAppearanceDialog: () => {
            actions.setDraft({ order: orderedListItemFields(values.fields), checked: values.fields })
        },
        saveAppearance: () => {
            const fields = values.draftFields
            if (fields.join() !== values.fields.join()) {
                actions.setFields(fields)
                // pinned: analytics event name and properties. Renaming them breaks dashboards.
                posthog.capture('today list appearance changed', {
                    secondary_fields: fields,
                    secondary_field_count: fields.length,
                })
            }
            actions.closeAppearanceDialog()
        },
    })),
])
